<?php
declare(strict_types=1);
/** One reviewed repair of the imported workforce, preserving account and relational IDs. */
function correction_document():array { $p=EP_ROOT.'/private/prepared-data-v25.json';if(!is_file($p))fail('ملف تصحيح V25 غير موجود؛ ارفع حزمة الاستضافة.');return decode(file_get_contents($p)); }
function correction_plan(array $doc):array {
 $users=query('SELECT * FROM ep_users')->fetchAll();$rows=[];$errors=[];$seen=[];$codes=[];
 foreach($doc['people']as $r){$serial=(int)$r['A'];$code='EMP-'.str_pad((string)$serial,4,'0',STR_PAD_LEFT);$previous=current(array_filter($doc['previous_people'],fn($p)=>$p['B']===$r['B']));$found=[];
  foreach($users as $u){if($u['role']==='admin')continue;$p=decode($u['profile_json']);$sameCivil=!empty($r['D'])&&!empty($p['civil_id'])&&(string)$p['civil_id']===(string)$r['D'];$oldSerial=$previous&&isset($p['setup_serial'])&&(int)$p['setup_serial']===(int)$previous['A'];if($sameCivil||$oldSerial||$u['name']===$r['B'])$found[(int)$u['id']]=$u;}
  if(count($found)>1)$errors[]='تعارض هوية: '.$r['B'];$target=$found?array_values($found)[0]:null;if($target&&$target['name']!==$r['B'])$errors[]='الاسم لا يطابق الهوية: '.$r['B'];if($target&&isset($seen[$target['id']]))$errors[]='موظف مرتبط بأكثر من اسم';if($target)$seen[$target['id']]=true;
  if($serial<1||isset($codes[$code]))$errors[]='مسلسل مكرر أو غير صالح';$codes[$code]=true;$rows[]=['serial'=>$serial,'name'=>$r['B'],'id'=>$target?(int)$target['id']:null,'old_code'=>$target?employee_key($target):'','new_code'=>$code];
 }
 foreach($users as $u)if($u['role']!=='admin'&&!isset($seen[$u['id']])&&isset($codes[employee_key($u)]))$errors[]='كود مستخدم لموظف خارج دفعة التصحيح: '.employee_key($u);
 foreach($users as $a)if($a['role']==='admin'){$adminProfile=decode($a['profile_json']);$adminCode=(string)($adminProfile['employee_code']??$a['username']);if(isset($codes[$adminCode]))$errors[]='كود المشرف يتعارض مع كود موظف؛ راجع الهوية قبل التصحيح';if(query("SELECT id FROM ep_history WHERE employee_code=? AND kind<>'salary_history'",[$adminCode])->fetch())$errors[]='توجد بيانات موظف تاريخية للمشرف تحتاج مراجعة';foreach(['ep_events','ep_payroll','ep_bank_payroll','ep_locations']as $table)if(query('SELECT id FROM '.$table.' WHERE user_id=?',[$a['id']])->fetch())$errors[]='توجد سجلات تشغيل للمشرف تحتاج مراجعة قبل فصل حسابه';if(query("SELECT id FROM ep_records WHERE user_id=? AND module NOT IN ('service_period','service_terms')",[$a['id']])->fetch())$errors[]='توجد سجلات موظف للمشرف تحتاج مراجعة';}
 foreach($rows as $r)if($r['id']){foreach(query('SELECT * FROM ep_history WHERE employee_code=?',[ $r['old_code'] ])->fetchAll()as $h)if(in_array($h['kind'],['payroll','bank'],true))$errors[]='يوجد كشف تاريخي يحتاج مراجعة قبل التصحيح: '.$r['name'];}
 $periods=[];foreach($doc['periods']as $p){$serial=(int)$p['A'];$person=current(array_filter($doc['people'],fn($r)=>(int)$r['A']===$serial));if(!$person||$p['B']!==$person['B']){$errors[]='اسم فترة لا يطابق المسلسل';continue;}$from=valid_date($p['C']);$to=valid_date($p['D']?:null);if(!$from||($to&&$to<$from))$errors[]='تاريخ فترة غير صالح';foreach($periods[$serial]??[]as $v)if($from<=($v[1]??'9999-12-31')&&($to??'9999-12-31')>=$v[0])$errors[]='فترات متداخلة';$periods[$serial][]=[$from,$to];if(!in_array($p['E'],array_column($doc['companies'],'B'),true)||($p['F']&&!in_array($p['F'],array_column($doc['companies'],'B'),true)))$errors[]='شركة غير معروفة';}
 $salaryKeys=[];foreach($doc['salaries']as $s){$person=current(array_filter($doc['people'],fn($r)=>(int)$r['A']===(int)$s['serial']));$date=valid_date($s['date']);$key=$s['serial'].'|'.$s['date'];if(!$person||$person['B']!==$s['name']||!$date||isset($salaryKeys[$key])||!is_numeric($s['salary'])||$s['salary']<0||(!$s['fixed_salary']&&$s['salary']!=0))$errors[]='سجل راتب غير صالح';$salaryKeys[$key]=true;$inside=false;foreach($periods[(int)$s['serial']]??[]as [$from,$to])if($date>=$from&&$date<=($to??'9999-12-31'))$inside=true;if(!$inside)$errors[]='راتب خارج فترة الخدمة: '.$s['name'];}
 foreach($doc['people']as $person){$serial=(int)$person['A'];if(empty($periods[$serial]))$errors[]='فترة خدمة مفقودة: '.$person['B'];foreach($periods[$serial]??[]as [$from,$to])if(!array_filter($doc['salaries'],fn($s)=>(int)$s['serial']===$serial&&$s['date']===$from))$errors[]='راتب بداية فترة الخدمة مفقود: '.$person['B'];}
 foreach($rows as $r)if($r['id']){foreach(['ep_payroll','ep_bank_payroll']as $table)if(query('SELECT id FROM '.$table." WHERE user_id=? AND status='approved'",[$r['id']])->fetch())$errors[]='يوجد كشف معتمد؛ راجعه قبل تصحيح بيانات '.$r['name'];if(query("SELECT id FROM ep_records WHERE user_id=? AND module='service_terms'",[$r['id']])->fetch())$errors[]='توجد شروط خدمة مؤرخة تحتاج مطابقة: '.$r['name'];}
 return ['rows'=>$rows,'errors'=>array_values(array_unique($errors)),'counts'=>['companies'=>count($doc['companies']),'employees'=>count($rows),'periods'=>count($doc['periods']),'salaries'=>count($doc['salaries'])]];
}
function correction_codes(array $v,array $map):array {foreach($v as $k=>$x){if(is_array($x))$v[$k]=correction_codes($x,$map);elseif(in_array($k,['code','employee_code'],true)&&is_string($x)&&isset($map[$x]))$v[$k]=$map[$x];}return $v;}
function correction_action(string $action,array $u,array $b):array {
 admin_only($u);$doc=correction_document();$hash=hash('sha256',jencode($doc));$done=query("SELECT value_json FROM ep_settings WHERE setting_key='data_correction_v25'")->fetchColumn();if($done){$v=decode($done);return ['already_applied'=>true,'rows'=>$v['mapping'],'errors'=>[],'hash'=>$hash,'counts'=>$v['counts']];}
