 if($action!=='correction_commit')fail('عملية غير موجودة.',404);if(!hash_equals($_SESSION['correction_preview']??'',(string)($b['hash']??''))||!hash_equals($hash,(string)($b['hash']??'')))fail('أعد معاينة التصحيح.');if($plan['errors'])fail(implode('\n',$plan['errors']));
 require_once __DIR__.'/backups.php';$backup=backup_run($u,'before_data_correction_v25');db()->beginTransaction();query('SELECT id FROM ep_users WITH (UPDLOCK, HOLDLOCK)');$plan=correction_plan($doc);if($plan['errors'])fail(implode('\n',$plan['errors']));
 $companies=[];foreach($doc['companies']as $r){$c=query('SELECT * FROM ep_companies WHERE name=?',[$r['B']])->fetch();if(!$c){$code=next_code('company');query('INSERT INTO ep_companies(code,name,legal_name,bank_name,bank_account,labor_file,active,created_at) VALUES(?,?,?,?,?,?,?,?)',[$code,$r['B'],$r['C'],str_replace('COMMERCAIL','COMMERCIAL',$r['D']),trim($r['E']),$r['F'],$r['G']==='مفعلة'?1:0,utc_now()]);$c=company_by_code($code);}else query('UPDATE ep_companies SET legal_name=?,bank_name=?,bank_account=?,labor_file=?,active=? WHERE id=?',[$r['C'],str_replace('COMMERCAIL','COMMERCIAL',$r['D']),trim($r['E']),$r['F'],$r['G']==='مفعلة'?1:0,$c['id']]);$companies[$r['B']]=$c['code'];}
 $map=[];$staff=[];foreach($plan['rows']as $item){$r=current(array_filter($doc['people'],fn($p)=>(int)$p['A']===$item['serial']));$id=$item['id'];if($id){$u0=query('SELECT * FROM ep_users WHERE id=?',[$id])->fetch();$p=array_replace(decode($u0['profile_json']),setup_profile($r));$map[$item['old_code']]=$item['new_code'];}else{$p=setup_profile($r);$login='staff-'.bin2hex(random_bytes(8));query("INSERT INTO ep_users(username,password_hash,name,role,active,profile_json,created_at) VALUES(?,?,?,'employee',0,?,?)",[$login,password_hash(bin2hex(random_bytes(32)),PASSWORD_DEFAULT),$r['B'],jencode($p),utc_now()]);$id=(int)db()->lastInsertId();}$p['employee_code']=$item['new_code'];query('UPDATE ep_users SET profile_json=? WHERE id=?',[jencode($p),$id]);$staff[$item['serial']]=query('SELECT * FROM ep_users WHERE id=?',[$id])->fetch();}
 // Rewrite references once from original values, so code shifts never cascade.
 $histories=query('SELECT id,employee_code,body_json FROM ep_history')->fetchAll();$temporary='V25-'.bin2hex(random_bytes(6)).'-';foreach($histories as $h)if(isset($map[$h['employee_code']]))query('UPDATE ep_history SET employee_code=? WHERE id=?',[$temporary.$h['id'],$h['id']]);foreach($histories as $h)if(isset($map[$h['employee_code']]))query('UPDATE ep_history SET employee_code=?,body_json=? WHERE id=?',[$map[$h['employee_code']],jencode(correction_codes(decode($h['body_json']),$map)),$h['id']]);
 foreach($staff as $serial=>$s){$id=(int)$s['id'];query("DELETE FROM ep_records WHERE user_id=? AND module='service_period'",[$id]);query("DELETE FROM ep_history WHERE employee_code=? AND kind='salary_history'",[employee_key($s)]);query("DELETE FROM ep_payroll WHERE user_id=? AND status='draft'",[$id]);query("DELETE FROM ep_bank_payroll WHERE user_id=? AND status='draft'",[$id]);$pp=array_values(array_filter($doc['periods'],fn($p)=>(int)$p['A']===$serial));usort($pp,fn($a,$b)=>strcmp($a['C'],$b['C']));$profile=decode($s['profile_json']);$latest=null;
  foreach($pp as $r){$note=$r['K']??'';$v=['company_code'=>$companies[$r['E']],'residence_company_code'=>$r['F']?$companies[$r['F']]:'','department'=>$r['G'],'job_title'=>$r['H'],'staff_type'=>['شريك'=>'partner','مكتب'=>'office','مندوب'=>'rep','عن بُعد'=>'remote'][$r['I']],'attendance'=>!str_contains($note,'لا يخضع'),'leave'=>$r['J']==='نعم','payroll'=>!str_contains($note,'تحويل بنك فقط'),'bank'=>true,'note'=>$note];query("INSERT INTO ep_records(module,user_id,title,date_from,date_to,status,body_json,created_at,updated_at) VALUES('service_period',?,?,?,?,'approved',?,?,?)",[$id,'فترة خدمة مصححة V25',$r['C'],$r['D']?:null,jencode($v),utc_now(),utc_now()]);$latest=$v;}
  if(!$latest)fail('فترة الخدمة مفقودة');$profile=array_replace($profile,['company_code'=>$latest['company_code'],'residence_company_code'=>$latest['residence_company_code'],'attendance_required'=>$latest['attendance'],'leave_eligible'=>$latest['leave'],'payroll_visible'=>$latest['payroll'],'bank_visible'=>true]);$ss=array_values(array_filter($doc['salaries'],fn($r)=>(int)$r['serial']===$serial));usort($ss,fn($a,$b)=>strcmp($a['date'],$b['date']));$current=['salary'=>0,'fixed_salary'=>false];foreach($ss as $r){$body=['code'=>employee_key($s),'effective_from'=>$r['date'],'salary'=>(float)$r['salary'],'fixed_salary'=>$r['fixed_salary'],'note'=>$r['note']];query('INSERT INTO ep_history(kind,employee_code,period_key,body_json,imported_at,imported_by) VALUES(?,?,?,?,?,?)',['salary_history',employee_key($s),$r['date'],jencode($body),utc_now(),$u['id']]);if($r['date']<=local_time()->format('Y-m-d'))$current=$r;}$profile['fixed_salary']=$current['fixed_salary'];if($serial===8)$profile['additional_job']='مندوب الشؤون والجوازات';query('UPDATE ep_users SET hired_on=?,salary=?,department=?,job_title=?,staff_type=?,profile_json=? WHERE id=?',[$pp[0]['C'],(float)$current['salary'],$latest['department'],$latest['job_title'],$latest['staff_type'],jencode($profile),$id]);}
 // Remove employment artefacts belonging to administrative-only accounts; retain audit/actions.
 foreach(query("SELECT * FROM ep_users WHERE role='admin'")->fetchAll()as $a){$p=decode($a['profile_json']);$old=(string)($p['employee_code']??$a['username']);query("DELETE FROM ep_records WHERE user_id=? AND module IN ('service_period','service_terms')",[$a['id']]);query("DELETE FROM ep_history WHERE employee_code=? AND kind='salary_history'",[$old]);foreach(['employee_code','setup_serial','fixed_salary','company_code','residence_company_code','attendance_required','leave_eligible','payroll_visible','bank_visible','bank_salary']as $k)unset($p[$k]);query('UPDATE ep_users SET hired_on=NULL,salary=0,staff_type=?,department=?,job_title=?,show_sick=0,profile_json=? WHERE id=?',['system','','المشرف العام',jencode($p),$a['id']]);}
 $mapping=[];foreach($staff as $serial=>$s)$mapping[]=['serial'=>$serial,'name'=>$s['name'],'code'=>employee_key($s),'id'=>(int)$s['id'],'new_code'=>employee_key($s)];$seq=max(count($staff),(int)(json_decode(query("SELECT value_json FROM ep_settings WHERE setting_key='sequence_employee'")->fetchColumn()?:'0',true)));query("MERGE INTO ep_settings WITH (HOLDLOCK) AS target USING (VALUES (?, ?)) AS source (setting_key, value_json) ON target.setting_key=source.setting_key WHEN MATCHED THEN UPDATE SET value_json=source.value_json WHEN NOT MATCHED THEN INSERT (setting_key, value_json) VALUES (source.setting_key, source.value_json);",['sequence_employee',jencode($seq)]);
 query('INSERT INTO ep_settings(setting_key,value_json) VALUES(?,?)',['data_correction_v25',jencode(['hash'=>$hash,'mapping'=>$mapping,'counts'=>$plan['counts'],'backup'=>$backup['id']])]);query("DELETE FROM ep_settings WHERE setting_key='prepared_import_v24'");query('INSERT INTO ep_settings(setting_key,value_json) VALUES(?,?)',['prepared_import_v24',jencode($mapping)]);audit('data_correction','V25',['counts'=>$plan['counts'],'backup'=>$backup['id']]);db()->commit();unset($GLOBALS['EP_SERVICE_CACHE'],$GLOBALS['EP_SALARY_CACHE']);return ['mapping'=>$mapping,'backup_id'=>$backup['id']];
